        {},
        {
          intro: {
            playbackId: 'intro-3',
            parentPlaybackId: 'ext-3',
            programId: 'radio-1',
            playbackRequestId: 'intro-3',
            url: 'u',
            startedAt: '2026-01-01T00:00:00.000Z',
            status: 'failed',
            failureReason: 'codec',
          },
        },
      ),
    );
